<?php
declare(strict_types=1);require_once __DIR__.'/../includes/auth.php';require_login();require_role(['administrador']);require_once __DIR__.'/../config/database.php';verify_csrf();
$mensaje='';$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){
 $accion=$_POST['accion']??'';
 if($accion==='crear'){
  $nombre=trim($_POST['nombre']??'');$usuario=trim($_POST['usuario']??'');$pass=$_POST['password']??'';$rol=$_POST['rol']??'consulta';
  if(!$nombre||!preg_match('/^[a-zA-Z0-9._-]{3,60}$/',$usuario)||strlen($pass)<10||!in_array($rol,['administrador','tesorero','consulta'],true))$error='Revisa los datos. Usuario de 3 a 60 caracteres y contraseña mínima de 10.';
  else try{$s=$pdo->prepare("INSERT INTO usuarios(nombre,usuario,password_hash,rol) VALUES(?,?,?,?)");$s->execute([$nombre,$usuario,password_hash($pass,PASSWORD_DEFAULT),$rol]);audit($pdo,'CREAR','usuarios',(int)$pdo->lastInsertId(),"Usuario $usuario");$mensaje='Usuario creado.';}catch(PDOException $ex){$error='El nombre de usuario ya existe.';}
 }elseif($accion==='estado'){
  $id=(int)($_POST['id']??0);if($id===(int)$_SESSION['usuario']['id'])$error='No puedes desactivar tu propia cuenta.';else{$s=$pdo->prepare("UPDATE usuarios SET estado=1-estado WHERE id=?");$s->execute([$id]);audit($pdo,'CAMBIAR_ESTADO','usuarios',$id,'Cambio de estado');$mensaje='Estado actualizado.';}
 }elseif($accion==='clave'){
  $id=(int)($_POST['id']??0);$pass=$_POST['password']??'';if(strlen($pass)<10)$error='La contraseña debe tener al menos 10 caracteres.';else{$s=$pdo->prepare("UPDATE usuarios SET password_hash=? WHERE id=?");$s->execute([password_hash($pass,PASSWORD_DEFAULT),$id]);audit($pdo,'CAMBIAR_CLAVE','usuarios',$id,'Restablecimiento de contraseña');$mensaje='Contraseña actualizada.';}
 }
}
$rows=$pdo->query("SELECT id,nombre,usuario,rol,estado,creado_en FROM usuarios ORDER BY id")->fetchAll();
?>
