<?php if($mensaje):?><p class="notice"><?=e($mensaje)?></p><?php endif;?><?php if($error):?><p class="error"><?=e($error)?></p><?php endif;?>
<section class="panel"><h3>Crear usuario</h3><form method="post" class="form-grid"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="accion" value="crear"><div><label>Nombre completo</label><input name="nombre" maxlength="150" required></div><div><label>Usuario</label><input name="usuario" required pattern="[a-zA-Z0-9._-]{3,60}"></div><div><label>Contraseña inicial (mínimo 10 caracteres)</label><input type="password" name="password" minlength="10" required></div><div><label>Rol</label><select name="rol"><option value="tesorero">Tesorero</option><option value="consulta">Consulta</option><option value="administrador">Administrador</option></select></div><div class="wide"><button class="btn">Crear usuario</button></div></form></section>
<section class="panel"><h3>Usuarios registrados</h3><div class="table-wrap"><table><thead><tr><th>Nombre</th><th>Usuario</th><th>Rol</th><th>Estado</th><th>Creado</th><th>Acciones</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['nombre'])?></td><td><?=e($r['usuario'])?></td><td><?=e($r['rol'])?></td><td><?= $r['estado']?'Activo':'Inactivo'?></td><td><?=e($r['creado_en'])?></td><td><form method="post" class="inline-form"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="accion" value="estado"><input type="hidden" name="id" value="<?=$r['id']?>"><button class="btn btn-small"><?=$r['estado']?'Desactivar':'Activar'?></button></form><form method="post" class="inline-form"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="accion" value="clave"><input type="hidden" name="id" value="<?=$r['id']?>"><input type="password" name="password" placeholder="Nueva contraseña" minlength="10" required><button class="btn btn-small">Cambiar clave</button></form></td></tr><?php endforeach;?></tbody></table></div></section></main></div></body></html>